"""Paid same-day service receipts survive reload and retain exactly-once purchase guards."""
import ast,hashlib,json
from playwright.sync_api import sync_playwright
from test_mobile_rendering import ROOT,html
source=(ROOT/'assets/game.js').read_text();tree=ast.parse((ROOT/'tests/test_private_services.py').read_text());fixture=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='probe' for t in n.targets))
probe=r'''window.__receiptRoundtrip=kind=>{const fixture=__privateFixture(kind,100);__townTest.step(1);const raw=archivePayload(),before=JSON.parse(raw),total=totalMoney(),purchases=G.privateServiceProvision,paid=purchases.tuition+purchases.memberships+purchases.vouchers;if(!(paid>0))throw Error('No paid private service fixture');const benefit=()=>kind==='school'?localCivicCoverage('school',fixture.poor):privateFireResponse(readBuild(G.households[fixture.poor].home)),benefitBefore=benefit();if(!hydrateSave(raw))throw Error('Valid paid receipt archive rejected');const restored=JSON.parse(archivePayload()),cashBefore=JSON.stringify([G.treasury,G.region,G.households.map(h=>h.cash),G.firms.map(f=>f.cash)]),learningBefore=JSON.stringify(G.people.map(p=>p.privateLearningDays||0)),wholeBefore=archivePayload();privateServiceDay();return {kind,paid,sameDayWholeStateUnchanged:wholeBefore===archivePayload(),paidBenefitBefore:benefitBefore,paidBenefitAfter:benefit(),paidBenefitPreserved:benefitBefore===benefit(),privateReceiptPreserved:JSON.stringify(before.privateServiceProvision)===JSON.stringify(restored.privateServiceProvision),publicReceiptPreserved:JSON.stringify(before.serviceProvision)===JSON.stringify(restored.serviceProvision),sameDayCashUnchanged:cashBefore===JSON.stringify([G.treasury,G.region,G.households.map(h=>h.cash),G.firms.map(f=>f.cash)]),learningUnchanged:learningBefore===JSON.stringify(G.people.map(p=>p.privateLearningDays||0)),totalConserved:Math.abs(totalMoney()-total)<.001};};
window.__receiptPolicyEdit=()=>{__privateFixture('school',100);__townTest.step(1);const publicBefore=JSON.stringify(G.serviceProvision),privateBefore=JSON.stringify(G.privateServiceProvision);draftPolicy={...G.policy,healthBudget:0,educationBudget:0,pensionDaily:0,privateTuitionCap:0};enactPolicyPackage();const money=totalMoney(),day=G.day,raw=archivePayload();if(!hydrateSave(raw)||G.day!==day||money!==totalMoney()||JSON.stringify(G.serviceProvision)!==publicBefore||JSON.stringify(G.privateServiceProvision)!==privateBefore)throw Error('Enacted policy rewrote prior paid receipt');return {sameDayPolicyEditPreservedPurchases:true,currentHealthAuthorization:G.policy.healthBudget,recordedPriorHealthAuthorization:G.serviceProvision.health.authorized};};
window.__receiptFaults=()=>{__privateFixture('school',100);__townTest.step(1);const raw=archivePayload(),cash=totalMoney(),faults={publicOverpay:g=>g.serviceProvision.health.paid=g.serviceProvision.health.requested+1,publicFuture:g=>g.serviceProvision.health.day=g.day+1,publicBadCoverage:g=>g.serviceProvision.health.coverage=null,privateWrongHousehold:g=>g.privateServiceProvision.school['999999']=.1,privateWrongProvider:g=>g.privateServiceProvision.allocations['999999']={},privateNegativeSubsidy:g=>Object.values(Object.values(g.privateServiceProvision.allocations)[0])[0].subsidy=-1,privateInconsistentTotals:g=>g.privateServiceProvision.vouchers++,privateFuture:g=>g.privateServiceProvision.day=g.day+1,privateBadCoverage:g=>g.privateServiceProvision.school[Object.keys(g.privateServiceProvision.school)[0]]=2};const checks=[];for(const [name,fault]of Object.entries(faults)){const g=JSON.parse(raw);fault(g);const before=archivePayload(),rng=rngState,head=JSON.stringify([saveEpoch,saveTown,saveRevision,saveOrder]),caller=JSON.stringify(g);if(hydrateSave(g)||archivePayload()!==before||rngState!==rng||head!==JSON.stringify([saveEpoch,saveTown,saveRevision,saveOrder])||caller!==JSON.stringify(g))throw Error('Receipt fault not rejected atomically: '+name);checks.push(name)}
 const missing=JSON.parse(raw);missing.schema=5;delete missing.serviceProvision;delete missing.privateServiceProvision;const missingCaller=JSON.stringify(missing);if(!hydrateSave(missing)||JSON.stringify(missing)!==missingCaller||G.serviceProvision!==null||G.privateServiceProvision!==null||Math.abs(cash-totalMoney())>.001)throw Error('Legacy missing observations rejected or moved money');
 const stale=JSON.parse(raw);for(const r of Object.values(stale.serviceProvision))r.day=stale.day-1;stale.privateServiceProvision.day=stale.day-1;if(!hydrateSave(stale)||G.serviceProvision!==null||G.privateServiceProvision!==null||Math.abs(cash-totalMoney())>.001)throw Error('Stale observations changed money or were used as current purchases');return {atomicRejected:checks,legacyMissingObservationsAccepted:true,staleObservationsInvalidatedWithoutMovingMoney:true};};'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',fixture+'\n'+probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();rows=[p.evaluate('kind=>__receiptRoundtrip(kind)',kind) for kind in ['school','fire']];faults=p.evaluate('__receiptFaults()');policyEdit=p.evaluate('__receiptPolicyEdit()');b.close()
print(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'cases':rows,'archiveCases':faults,'policyEditCounterexample':policyEdit},indent=2),flush=True)
assert all(r['paidBenefitBefore']>0 for r in rows),rows
assert all(all(r[k] for k in ['paidBenefitPreserved','sameDayWholeStateUnchanged','privateReceiptPreserved','publicReceiptPreserved','sameDayCashUnchanged','learningUnchanged','totalConserved']) for r in rows),rows
print('PASS paid public/private receipt continuity and exactly-once same-day cash/learning')
